import json
import os

file_path = "storage/shared/progressor_outputs/all_transgen_logs.normalized.jsonl"

print(f"Attempting to read first 5 lines of: {file_path}")

if not os.path.exists(file_path):
    print(f"Error: File not found at {file_path}")
else:
    try:
        with open(file_path, 'r') as f:
            for i, line in enumerate(f):
                if i >= 5: # Read only first 5 lines
                    break
                try:
                    # Attempt to parse as JSON to confirm structure
                    json_obj = json.loads(line)
                    print(f"Line {i+1}: {json.dumps(json_obj, indent=2)[:500]}...") # Print a snippet of the parsed JSON
                except json.JSONDecodeError as e:
                    print(f"Line {i+1} (Raw): {line.strip()[:500]}...")
                    print(f"  JSON Decode Error: {e}")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
